"""Emit post-seal observations without modifying sealed intake records/proposals."""
from pathlib import Path
from datetime import datetime, timezone
import json,csv,hashlib
P=Path(__file__).parent
POST=P/'postseal'
NOW=datetime.now(timezone.utc).isoformat()
existing_sources={x['source_id']:x for x in [json.loads(line) for line in (POST/'sources.jsonl').read_text().splitlines()]} if (POST/'sources.jsonl').exists() else {}
acq=[json.loads(x) for x in (POST/'acquisitions.jsonl').read_text().splitlines()]
sources=[]
def s(sid,edition,path,lineage,kind,lines,confirmed,limits,claim):
    a=next(x for x in acq if x['edition']==edition and x['path']==path)
    sources.append(dict(source_id=sid,lineage_id=lineage,material_type=kind,url=a['url'],fixed_version=a['source_commit'],location=f'{path}:{lines}',opened_utc=a['opened_utc'],read_utc=NOW,questions=['Q2','Q3','Q4','Q5','Q7'],cases=['G04-1','G04-2'],confirmed=confirmed,limits=limits,claim_relation=claim,sha256=a['sha256'],directly_read=True,count_as_independent_work=False,downstream_authored_work=True))
