for file in ['PUBLISHER-GEO-3348.json','PUBLISHER-GEO-3391.json','PR3348-summary.json','PR3391-summary.json']:
    d=json.loads((POST/file).read_text())
    sources.append(dict(source_id=d['source_id'],lineage_id=d['lineage_id'],material_type='publisher_merged_change',url=d['source_url'],fixed_version=d['sha'],location='doc/source/docs/user_guide/io.rst changed hunks or PR body',opened_utc=d['opened_utc'],time_precision=d['time_precision'],read_utc=NOW,questions=['Q4','Q7'],cases=['G04-1','G04-2'],confirmed=d['summary'],limits=d['limits'],claim_relation='Actual publisher change and rationale distinct from research proposal.',directly_read=True,count_as_independent_work=d['source_id'] in ['G083-P0','G083-P1'],downstream_authored_work=True))
for sid in ['G083-S15','G083-S16','G083-S17','G083-S18','G083-S19']:
    d=json.loads((POST/f'{sid}.json').read_text());d.update(material_type=d.pop('kind'),directly_read=True,count_as_independent_work=(sid=='G083-S15'),downstream_authored_work=True,fixed_version=d.get('merge_commit_sha'),location='publisher issue/PR body or merge comment',claim_relation='Publisher reasoning; same migration discussion and PRs count as one event.')
    sources.append(d)
for x in sources:
    prior=existing_sources.get(x['source_id'])
    if prior and 'read_utc' in prior:
        x['read_utc']=prior['read_utc']
(POST/'sources.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in sources))

